<!doctype html>
<html lang="de">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Rechnungstool</title>
<style>
:root{--bg:#f5f7fb;--card:#fff;--border:#dfe4ec;--text:#172033;--muted:#667085;--primary:#2563eb;--primary-dark:#1d4ed8;--soft:#eef4ff;--warn:#fff8db;--warn-border:#ecd36b;--shadow:0 8px 28px rgba(31,41,55,.08)}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",Arial,sans-serif;background:var(--bg);margin:0;color:var(--text)}
.page{max-width:1580px;margin:auto;padding:28px 32px 48px}.top{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:22px}.top h1{font-size:28px;margin:0 0 5px}.subtitle{color:var(--muted);font-size:14px}.top-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.back,.secondary-button{display:inline-flex;align-items:center;text-decoration:none;color:#344054;background:#fff;border:1px solid var(--border);border-radius:9px;padding:9px 12px;font-weight:600;font-size:14px}.back:hover,.secondary-button:hover{background:#f8fafc}
.notice,.filters,.preview-box,.results{background:var(--card);border:1px solid var(--border);border-radius:14px;box-shadow:var(--shadow)}.notice{padding:14px 16px;margin-bottom:16px;border-left:4px solid var(--primary);box-shadow:none}.filters{display:grid;grid-template-columns:150px 150px minmax(220px,1fr) minmax(260px,1.4fr) auto;gap:12px;align-items:end;padding:16px;margin-bottom:16px}.filters label{display:flex;flex-direction:column;gap:6px;font-size:12px;font-weight:700;color:#475467;text-transform:uppercase;letter-spacing:.04em}.filters input,.filters select{width:100%;font:inherit;color:var(--text);padding:10px 11px;border:1px solid #cfd6e1;border-radius:9px;background:#fff;text-transform:none;letter-spacing:normal}.filters input:focus,.filters select:focus{outline:3px solid #dbeafe;border-color:#60a5fa}.filters button{font:inherit;font-weight:700;padding:10px 16px;border:0;border-radius:9px;background:var(--primary);color:#fff;cursor:pointer;white-space:nowrap}.filters button:hover{background:var(--primary-dark)}
.meta{margin:14px 2px;color:var(--muted);font-size:13px}.preview-box{padding:18px;margin:18px 0 20px;scroll-margin-top:18px}.preview-head,.section-head{display:flex;justify-content:space-between;align-items:center;gap:16px}.preview-box h2,.results h2{margin:2px 0 0;font-size:21px}.preview-box h3{margin:20px 0 10px;font-size:15px}.eyebrow{font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.08em;color:var(--primary)}.warning{background:var(--warn);border:1px solid var(--warn-border);padding:10px 12px;border-radius:9px}.results{overflow:hidden}.section-head{padding:15px 16px;border-bottom:1px solid var(--border)}.count-badge{display:inline-flex;min-width:34px;height:28px;align-items:center;justify-content:center;border-radius:999px;background:var(--soft);color:var(--primary-dark);font-weight:800;font-size:13px;padding:0 10px}.table-wrap{overflow:auto}table{border-collapse:separate;border-spacing:0;width:100%;background:#fff;font-size:13px}th,td{border-bottom:1px solid #edf0f4;padding:10px 12px;vertical-align:top;text-align:left}th{position:sticky;top:0;background:#f8fafc;color:#475467;font-size:11px;text-transform:uppercase;letter-spacing:.04em;white-space:nowrap;z-index:1}tbody tr:hover{background:#f8fbff}.selected-row{background:#eef5ff!important}.muted{color:var(--muted)}.preview-link{display:inline-flex;text-decoration:none;color:#fff;background:var(--primary);padding:6px 10px;border-radius:7px;font-weight:700;font-size:12px;white-space:nowrap}.preview-link:hover{background:var(--primary-dark)}
@media(max-width:1050px){.filters{grid-template-columns:1fr 1fr}.filters button{width:100%}.page{padding:20px}.top{align-items:center}}@media(max-width:650px){.page{padding:14px}.top{flex-direction:column}.filters{grid-template-columns:1fr}.preview-head,.section-head{align-items:flex-start;flex-direction:column}.secondary-button{width:100%;justify-content:center}}
</style>
</head>
<body>
<div class="page">
    <div class="top"><div><h1>Rechnungstool</h1><div class="subtitle">Vorschau / Testlauf · aktuell ausschließlich lesend</div></div><div class="top-actions"><a class="back" href="{{ route('dashboard') }}">← Hauptmenü</a></div></div>
    @include('fakturierung.preview')
</div>
</body>
</html>